import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,M as r,N as i,O as a,P as o,S as s,T as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g}from"./shared-JA1PGxXr.js";import{t as _}from"./eye-DxnR9WGB.js";import{t as v}from"./shield-check-r4OxDZ2w.js";import{t as y}from"./CodeEditor-DqHMt3P8.js";var b=e();function x({module:e}){return(0,b.jsxs)(i,{children:[(0,b.jsx)(r,{variant:`project`,chip:e??`Блок 7 · Объектная модель`,title:`Представление и вычисляемое свойство Task`,intro:`Добавим к уже знакомой Task удобный текст для человека и вычисляемую подпись статуса. Разберём, что означает подчёркивание в имени, и исследуем getter и setter отдельно, не меняя выбранные методы модели.`,tags:[{icon:(0,b.jsx)(_,{size:14}),label:`строка для человека`},{icon:(0,b.jsx)(v,{size:14}),label:`границы доступа`}]}),(0,b.jsxs)(o,{number:`00`,title:`Одна задача, несколько способов её прочитать`,children:[(0,b.jsx)(a,{children:`В прошлых занятиях у Task появились четыре поля: id, title, priority и is_done. Методы rename, set_priority и mark_done изменяют эти данные. Теперь мы научимся получать из них понятную строку, которая показывает текущее состояние задачи, даже если оно изменилось минуту назад.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Что уже умеем`,description:`Создаём одну Task в app.models, читаем четыре поля и меняем их через три известных метода.`},{title:`Что мешает`,description:`print(task) пока не даёт удобной карточки. Сохранять ещё одно поле со статусом опасно: данные могут разойтись.`},{title:`Что получим`,description:`Строку через __str__, подпись через @property и опыт с безопасным setter на другом классе.`}]}),(0,b.jsx)(`p`,{children:`Путь будет таким: сначала отделим возврат строки от печати, затем вычислим подпись статуса, соберём карточку Task и проверим её после действий. В конце узнаем, что property может контролировать присваивание, но не защищает все поля автоматически.`}),(0,b.jsx)(`p`,{children:`Перед редактированием открой свою app.models.Task и проверь, что она существует в проекте. Если поля или методы ещё не готовы, сперва закончи предыдущую практику. Здесь нельзя создавать вторую Task только ради примера: тогда новая строка окажется в классе, который приложение вообще не использует.`})]}),(0,b.jsxs)(o,{number:`01`,title:`__str__: вернуть строку, а не напечатать её`,children:[(0,b.jsx)(a,{children:`Если написать print для обычного объекта без собственного строкового представления, Python часто покажет техническую запись с названием класса и адресом. Для человека полезнее короткий текст. Метод __str__(self) сообщает Python, какую именно строку вернуть при str(obj).`}),(0,b.jsx)(`p`,{children:`Слово return означает «передай результат вызвавшему коду». print выполняет другое действие: показывает значение в терминале и возвращает None. Поэтому внутри __str__ нужно написать return, а печатать можно снаружи: text = str(obj), затем print(text). Такой текст пригодится и без терминала.`}),(0,b.jsx)(y,{caption:`Независимый пример: Notice, не готовый код Task`,code:`class Notice:
    def __init__(self, number, message):
        self.number = number
        self.message = message

    def __str__(self):
        return f"Сообщение {self.number}: {self.message}"

notice = Notice(4, "Отчёт")
text = str(notice)
print(text)`}),(0,b.jsx)(`p`,{children:`В фигурных скобках f-строки находятся выражения. self.number и self.message берут данные именно того экземпляра, для которого вызвали метод. Если поменять notice.message, следующее str(notice) соберёт другой текст. Готовая строка не хранится в классе и не обновляется вручную.`}),(0,b.jsx)(c,{question:`Какой __str__ позволит записать строку в text = str(notice)?`,left:{title:`Печать внутри`,code:`def __str__(self):
    print(self.message)`,note:`Покажет сообщение, но вернёт None. str(notice) завершится TypeError.`},right:{title:`Возврат наружу`,code:`def __str__(self):
    return self.message`,note:`Вернёт str. Решение о печати принимает вызывающий код.`},preferred:`right`,explanation:`__str__ обязан вернуть объект типа str. Вызов print не заменяет return.`}),(0,b.jsx)(`p`,{children:`Отдельная функция repr(obj) обычно нужна разработчику для диагностики. Мы не меняем __repr__: здесь нужен обычный текст через str. При print(obj) Python получает строковое представление объекта и выводит его; при text = str(obj) мы получаем то же представление без вывода.`}),(0,b.jsx)(`p`,{children:`Проверь разницу на Notice: значение text после str(notice) можно сравнить с ожидаемым текстом или сохранить в переменную. Отдельный print(text) лишь покажет результат. Затем замени message на «Готово» и ещё раз вызови str: меняется результат, потому что self.message читается заново, а не потому, что print что-то сохранил.`}),(0,b.jsx)(t,{rows:[[(0,b.jsx)(b.Fragment,{children:`str(notice)`}),`вернуть понятный текст, не печатая`],[(0,b.jsx)(b.Fragment,{children:`print(notice)`}),`получить строку объекта и вывести`],[(0,b.jsx)(b.Fragment,{children:`repr(notice)`}),`получить диагностическое представление`]]})]}),(0,b.jsxs)(o,{number:`02`,title:`@property: вычислять подпись при чтении`,children:[(0,b.jsx)(a,{children:`У Task уже есть is_done: False означает, что задача ещё не выполнена, True означает, что выполнена. Если дополнительно сохранять status_text, после mark_done пришлось бы обновить два поля. Забыли обновить одно, и в одной задаче одновременно окажутся True и «не завершена».`}),(0,b.jsx)(`p`,{children:`Обычный метод label(self) читают со скобками: lamp.label(). Декоратор @property позволяет обращаться к тому же вычислению как к атрибуту: lamp.label. Python вызывает метод при каждом таком чтении. Это getter, то есть способ получить значение, а не ещё одно сохранённое поле.`}),(0,b.jsx)(y,{caption:`Разобранный пример: Lamp`,code:`class Lamp:
    def __init__(self):
        self.is_on = False

    @property
    def label(self):
        return "Светит" if self.is_on else "Выключена"

lamp = Lamp()
print(lamp.label)
lamp.is_on = True
print(lamp.label)`}),(0,b.jsx)(`p`,{children:`Первый print покажет «Выключена», второй покажет «Светит». Ничего не работает в фоне: значение рассчитывается, когда код обращается к lamp.label. Попытка вызвать lamp.label() приведёт к TypeError: getter уже вернул строку, а строка не является вызываемой функцией.`}),(0,b.jsx)(s,{statement:(0,b.jsx)(b.Fragment,{children:`После изменения lamp.is_on для нового текста нужно отдельно присвоить lamp.label = "Светит".`}),isTrue:!1,explanation:`Getter вычисляет результат при новом чтении. Для такого свойства без setter присваивание запрещено.`}),(0,b.jsx)(`p`,{children:`Теперь перенесём принцип, не копируя готовое решение. У Task свойство должно называться status_label и читать только self.is_done. Договор о тексте одинаков во всём занятии: False даёт «не завершена», True даёт «выполнена». status_label нельзя дописывать в __init__ как ещё одно поле и не нужно присваивать при mark_done.`}),(0,b.jsx)(h,{caption:`Чтение подписи происходит по требованию`,children:(0,b.jsxs)(p,{label:`Один источник состояния`,children:[(0,b.jsx)(d,{title:`Task.is_done`,shape:`database`,children:(0,b.jsx)(`p`,{children:`Хранит True или False`})}),(0,b.jsx)(f,{label:`чтение свойства`}),(0,b.jsx)(d,{title:`status_label`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Getter выбирает русскую подпись`})}),(0,b.jsx)(f,{label:`передаёт строку`}),(0,b.jsx)(d,{title:`__str__`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Включает подпись в карточку`})}),(0,b.jsx)(f,{label:`возвращает`}),(0,b.jsx)(d,{title:`str / print`,shape:`terminator`,children:(0,b.jsx)(`p`,{children:`Получает текст или выводит его`})})]})}),(0,b.jsx)(`p`,{children:`На схеме только is_done хранит состояние. status_label выдаёт перевод этого флага в слова; __str__ позже сможет использовать полученную строку. После mark_done меняется флаг, а при следующем чтении меняется подпись. Это не вторая копия статуса и не запись в файл.`})]}),(0,b.jsxs)(o,{number:`03`,title:`Карточка отражает текущую Task`,children:[(0,b.jsx)(a,{children:`В существующую Task добавим два элемента: status_label и __str__. Для карточки нужны четыре фрагмента: номер id, название title, число priority и текст status_label. Между ними оставим привычные подписи «приоритет» и разделители |, чтобы формат был одинаковым при каждом выводе.`}),(0,b.jsx)(`p`,{children:`Возьми Task(7, "Купить хлеб", 2, False). До изменений её карточка должна выглядеть как «[7] Купить хлеб | приоритет: 2 | не завершена». Но этот пример показывает только требуемый результат: тело __str__ и getter ты напишешь сам. Оба метода читают данные, а не меняют их.`}),(0,b.jsx)(g,{code:`task = Task(7, "Купить хлеб", 2, False)
print(str(task))
task.rename("Купить молоко")
task.set_priority(4)
task.mark_done()
print(task)`,steps:[{line:0,note:`Существующий конструктор создаёт одну Task.`,vars:{id:`7`,is_done:`False`}},{line:1,note:`Предскажи строку до запуска.`,vars:{вывод:`[7] Купить хлеб | приоритет: 2 | не завершена`}},{line:2,note:`Меняется только название.`,vars:{title:`Купить молоко`}},{line:3,note:`Метод проверяет новое число перед изменением.`,vars:{priority:`4`}},{line:4,note:`Задача становится выполненной.`,vars:{is_done:`True`}},{line:5,note:`Строка заново читает четыре фрагмента.`,vars:{вывод:`[7] Купить молоко | приоритет: 4 | выполнена`}}]}),(0,b.jsx)(`p`,{children:`До запуска самостоятельно назови результат каждого действия. Если после rename карточка осталась прежней, проверь, что __str__ читает self.title, а не строку, однажды созданную в __init__. Если подпись не меняется после mark_done, проверь, что getter использует текущее self.is_done, а не запомненное значение.`}),(0,b.jsx)(`p`,{children:`Формат карточки фиксируем один раз: квадратные скобки вокруг id, далее title, затем «приоритет:» с числом и подпись статуса. Внутри __str__ достаточно читать self.id, self.title, self.priority и self.status_label. Если случайно написать self.status_label(), Python попробует вызвать строку и получит ошибку.`}),(0,b.jsx)(l,{question:`Как прочитать вычисляемую подпись внутри __str__?`,options:[`Через self.status_label без скобок`,`Через self.status_label() со скобками`,`Через новое сохранённое поле self.status_text`],correctIndex:0,explanation:`@property выполняет getter при чтении атрибута. Вызов скобками попытается вызвать уже возвращённую строку.`}),(0,b.jsx)(`p`,{children:`Проверь и отказ: set_priority(0) и rename("   ") должны выдавать ValueError и не менять карточку. Это обязанность валидирующих методов, созданных раньше. Повторное mark_done() оставляет задачу выполненной. Второй экземпляр Task не меняется вслед за первым: self всегда указывает на объект текущего вызова.`}),(0,b.jsx)(`p`,{children:`Не забывай проверять собственно строку: text = str(task) даёт значение типа str, а print(task) выводит такую же карточку. Сам __str__ ничего не должен менять. Перед каждым некорректным вызовом сохрани снимок str(task), после перехвата ValueError сравни его со свежей строкой: при правильной проверке они одинаковы.`})]}),(0,b.jsxs)(o,{number:`04`,title:`Инкапсуляция и setter: проверка перед записью`,children:[(0,b.jsx)(a,{children:`Инкапсуляция означает, что класс предлагает понятный способ работы со своим состоянием. Имя _level с одним подчёркиванием помечает внутреннюю деталь по соглашению разработчиков. Python не запрещает записать gauge._level напрямую, поэтому само имя не защищает значение.`}),(0,b.jsx)(`p`,{children:`Сравни два действия: task.set_priority(4) вызывает явный метод, а gauge.level = 4 может вызывать setter свойства level. Для этого getter отмечают @property, а метод записи отмечают @level.setter. Оба используют одно публичное имя level и внутреннее поле _level.`}),(0,b.jsx)(y,{caption:`Набросок отдельного Gauge, задание на setter остаётся самостоятельным`,code:`class Gauge:
    def __init__(self):
        self._level = level

    @property
    def level(self):
        return self._level

    @level.setter
    def level(self, new_value):
        # TODO: проверить тип и границы 1..5
        # TODO: только потом обновить _level
        pass`}),(0,b.jsx)(`p`,{children:`В setter сначала проверяют тип: допустим именно int, а bool не подходит, хотя True ведёт себя как число во многих выражениях Python. Затем проверяют диапазон от 1 до 5. При недопустимом вводе нужно поднять ValueError до присваивания. Лишь после успешных проверок новое число записывают в _level.`}),(0,b.jsx)(t,{rows:[[(0,b.jsx)(b.Fragment,{children:`gauge.level = 4`}),`setter проверяет число, затем обновляет _level`],[(0,b.jsx)(b.Fragment,{children:`gauge.level = 9`}),`ValueError, _level остаётся прежним`],[(0,b.jsx)(b.Fragment,{children:`gauge.level = True`}),`ValueError: bool не принимаем за int`],[(0,b.jsx)(b.Fragment,{children:`gauge._level = 9`}),`прямой обход setter, нарушение соглашения`]]}),(0,b.jsx)(`p`,{children:`Предскажи цепочку 2 → 4 → попытка 9. После отказа getter должен вернуть 4, поскольку ошибка не меняет предыдущее состояние. Если сначала записать 9, а потом проверить, исключение не откатит присваивание. Setter полезен именно как единое место проверки записи через публичное свойство, а не как абсолютный замок.`}),(0,b.jsx)(`p`,{children:`У setter и getter одинаковое имя level, но разные задачи. Выражение gauge.level читает внутреннее _level через getter. Выражение gauge.level = 4 передаёт число в параметр new_value у setter. Если ошибочно написать gauge.level(4), код попытается вызвать число, полученное от getter, и закончится TypeError.`}),(0,b.jsx)(n,{code:`class Meter:
    def __init__(self):
        self._power = 2

    @property
    def power(self):
        return self._power

    @power.setter
    def power(self, new_value):
        self._power = new_value
        if new_value < 1 or new_value > 5:
            raise ValueError("Только 1..5")`,question:`Почему Meter может сохранить 9 даже после ValueError?`,options:[`Поле меняется до проверки, исключение не отменяет запись`,`Getter всегда возвращает предыдущее число`,`Python запрещает имена с подчёркиванием`],correctIndex:0,explanation:`Сначала проверь локальное new_value, затем меняй _power. Для Gauge дополнительно отличай bool от int.`,fix:`    @power.setter
    def power(self, new_value):
        if type(new_value) is not int or not 1 <= new_value <= 5:
            raise ValueError("Нужно целое от 1 до 5")
        self._power = new_value`}),(0,b.jsx)(`p`,{children:`Исправление показано на Meter, чтобы принцип был виден, а setter для Gauge ты дописал самостоятельно. Не ставь внутри setter строку self.level = new_value: она снова вызовет setter с тем же именем и приведёт к рекурсии. Внутри используют self._level.`}),(0,b.jsx)(`p`,{children:`Проверь ещё один крайний случай: True является экземпляром bool и одновременно проходит проверку isinstance(True, int). Поэтому для учебного требования «строго целое число, но не bool» нужна проверка точного типа. Даже если условие диапазона приняло бы True за единицу, setter должен отклонить его без изменения _level.`}),(0,b.jsx)(s,{statement:(0,b.jsx)(b.Fragment,{children:`Одно подчёркивание делает запись gauge._level = 9 технически невозможной.`}),isTrue:!1,explanation:`Это соглашение о внутреннем атрибуте. Прямое присваивание обходит setter.`})]}),(0,b.jsxs)(o,{number:`05`,title:`Почему Task оставляет обычные методы`,children:[(0,b.jsx)(a,{children:`У Task уже существуют mark_done(), rename(new_title) и set_priority(new_priority). Они проверяют допустимость изменений и сохраняют прежний интерфейс проекта. Getter status_label добавляет удобное чтение, но не заменяет эти методы и ничего не записывает.`}),(0,b.jsx)(`p`,{children:`В учебном Gauge запись gauge.level = 4 проходит через setter. В основной Task изменение приоритета по-прежнему делаем через task.set_priority(4). Прямое task.priority = 9 может обойти проверку метода, поэтому так не следует обходить договор модели. Мы не меняем поля Task на _priority и не добавляем ей setter сейчас.`}),(0,b.jsx)(`p`,{children:`Точно так же rename(new_title) задаёт действие «переименовать», а mark_done() задаёт переход к завершённости. Прямое присваивание task.title или task.is_done технически возможно в нынешнем классе, но обойдёт соответствующий метод. Соблюдение этого правила зависит от кода, который использует Task.`}),(0,b.jsx)(m,{prompt:`Подбери действие к намерению`,leftTitle:`Выражение`,rightTitle:`Зачем нужно`,pairs:[{left:`task.mark_done()`,right:`завершить задачу`},{left:`task.set_priority(4)`,right:`проверить и изменить приоритет`},{left:`task.status_label`,right:`прочитать актуальную подпись`},{left:`str(task)`,right:`получить текст карточки`}],explanation:`Методы изменяют состояние, свойство читает вычисленное значение, __str__ возвращает представление.`}),(0,b.jsx)(`p`,{children:`У свойства status_label нет setter. Попытка присвоить task.status_label = "выполнена" вызовет AttributeError, а задача не завершится. Используй mark_done(): тогда изменится is_done и следующее чтение подписи станет правильным. Вновь создавать Task не нужно: дополняем существующий класс в app.models, сохраняя остальные методы.`}),(0,b.jsx)(`p`,{children:`Отдельный эксперимент с Gauge нужен, чтобы понять синтаксис setter на простом поле. Не переноси в Task конструкцию _level, не добавляй в неё property для каждого атрибута и не переписывай конструктор. Так у приложения сохраняется привычный интерфейс, а новая функциональность ограничивается чтением представления.`}),(0,b.jsx)(l,{question:`Что произойдёт после двух последовательных вызовов task.mark_done()?`,options:[`is_done останется True и новое чтение status_label даст «выполнена»`,`Каждый вызов переключит True обратно в False`,`Строка статуса сохранится в отдельное поле status_text`],correctIndex:0,explanation:`mark_done устанавливает завершённость, а getter читает текущее is_done.`})]}),(0,b.jsxs)(o,{number:`06`,title:`Строка для человека не заменяет данные для хранения`,children:[(0,b.jsx)(a,{children:`Строку «[7] Купить молоко | приоритет: 4 | выполнена» удобно показать на экране. Но хранить только её опасно: если изменится русский текст или разделители, программе будет трудно восстановить номер, название, число и логический флаг.`}),(0,b.jsx)(`p`,{children:`Для хранения нужен структурированный набор полей id, title, priority и is_done. В Python последнее поле имеет тип bool и значения True или False; в JSON используются true и false. Русская подпись status_label туда отдельным полем не входит: её снова можно вычислить из is_done после восстановления модели.`}),(0,b.jsx)(`p`,{children:`Не путай bool со словом на экране. True и False удобны программе для условий: if task.is_done проверяет реальное состояние. Человеку удобнее русская подпись. Встроив подпись прямо в данные, мы бы потеряли этот простой смысл поля и связали бы сохранение с языком интерфейса.`}),(0,b.jsxs)(h,{caption:`Один объект, два результата для разных потребителей`,children:[(0,b.jsxs)(p,{label:`Показ и будущая запись`,children:[(0,b.jsx)(d,{title:`Task`,shape:`database`,children:(0,b.jsx)(`p`,{children:`Четыре исходных поля`})}),(0,b.jsx)(f,{label:`str(task)`}),(0,b.jsx)(d,{title:`Карточка`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Текст с русской подписью для человека`})})]}),(0,b.jsxs)(p,{label:`Структура для хранения`,children:[(0,b.jsx)(d,{title:`Та же Task`,shape:`database`,children:(0,b.jsx)(`p`,{children:`id, title, priority, is_done`})}),(0,b.jsx)(f,{label:`следующий урок`}),(0,b.jsx)(d,{title:`Словарь`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Четыре поля с собственными типами`})})]})]}),(0,b.jsx)(`p`,{children:`Сейчас словарный CLI продолжает использовать прежний format_task(record), а рабочий JSON остаётся прежним. Здесь не пишем to_dict, from_dict или json.dumps: это следующий отдельный шаг. Проверять __str__ будем прямыми вызовами Task, не подменяя им существующий путь сохранения. Так вывод остаётся свободным менять оформление, а формат данных остаётся стабильным.`}),(0,b.jsx)(`p`,{children:`Представь изменение текста подписи на другой язык. Человек увидит иной текст, но id останется числом, priority тоже, а is_done останется логическим значением. Поэтому будущий to_dict должен передавать четыре исходных поля, а from_dict получать их обратно. Само преобразование изучим на следующем шаге.`})]}),(0,b.jsxs)(o,{number:`07`,title:`Практика: меняем модель, исследуем setter отдельно`,children:[(0,b.jsx)(a,{children:`Проверь, что в app.models уже есть одна Task с четырьмя полями и методами из предыдущих занятий. В практике сначала самостоятельно добавишь status_label и __str__, затем сравнишь карточки до и после изменений. Отдельный Gauge поможет проверить setter.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Предскажи`,description:`Для Task(7, «Купить хлеб», 2, False) назови исходную строку и подпись ещё до запуска.`},{title:`Сделай сам`,description:`Добавь в существующую Task getter status_label и возвращающий строку __str__. Не меняй CLI.`},{title:`Проверь перенос`,description:`После rename, set_priority и mark_done сравни строки, отказы и независимость двух объектов.`},{title:`Исследуй`,description:`В отдельном Gauge напиши setter: 2 → 4 → неверные 9 и True; после отказов уровень равен 4.`}]}),(0,b.jsx)(`p`,{children:`В конце объясни, почему чтение status_label не изменяет состояние, а будущий словарь для хранения должен сохранить bool. Убедись, что прежний словарный CLI работает и после добавления представления. Не оставляй демонстрационные вызовы на верхнем уровне app.models.`})]})]})}export{x as Lesson33};